"""Render coach review files from immutable computed evidence. No sports decisions or writes outside V12 docs."""
from pathlib import Path
import json,gzip,collections,hashlib,re
R=Path('docs/det-engine/v12');E=R/'evidence/final'
# Read all prerequisites before writing any dossier.
rows=json.load(gzip.open(E/'comparison.json.gz','rt'))
summary=json.loads((E/'comparison-summary.json').read_text())
repro=json.loads((R/'evidence/reproducibility.json').read_text())
commands=json.loads((R/'evidence/validation/commands.json').read_text())
assert repro['identical'] and len(commands)==4 and all(x['exitCode']==0 and not x.get('error') for x in commands)
for x in repro['comparison']:
 assert hashlib.sha256((E/x['file']).read_bytes()).hexdigest()==x['first']==x['replay']
def table(headers,data):
 return '\n'.join(['| '+' | '.join(headers)+' |','|'+'|'.join('---'for _ in headers)+'|']+['| '+' | '.join(str(x).replace('|','/')for x in row)+' |'for row in data])
def write(name,text):
 text=re.sub(r'(\d)(min|tests|séances|semaines|configurations)\b',r'\1 \2',text)
 for a,b in [('blocs15','blocs de 15'),('de10','de 10'),('que15','que 15'),('avec60','avec 60'),('reste60','reste 60'),('Position6','Position 6'),('de4','de 4'),('récupération250','récupération 250'),('conserve7','conserve 7'),('et30','et 30'),(';62','; 62'),(',112',', 112'),(',2999',', 2999'),(',6 todo',', 6 todo'),('Les12','Les 12'),('les600','les 600'),('à250','à 250'),('annonce30','annonce 30'),('moins55','moins 55')]: text=text.replace(a,b)
 (R/name).write_text(text.rstrip()+'\n')
def source_sessions(week,day):
 return '; '.join((s.get('title')or'Repos')+(' ['+s['catalogId']+']' if s.get('catalogId') else '')+' · '+str(s.get('durationMin',0))+' min' for s in week['sessions']if s['dayName']==day)
models={'justified_maintenance':'Maintien justifié','priority_duration':'Durée du rôle prioritaire','rest_density':'Repos raccourci dans la même fiche','controlled_intensity':'Domaine d’intensité supérieur','technical_segmentation':'Consolidation de position via deux fiches'}
reasons={'priority_source_or_individual_cap_exhausted':'Rôle prioritaire déjà à sa borne catalogue/individuelle actuelle ; aucune hausse inventée.','same_source_rest_is_fixed_do_not_rewrite_recipe':'La récupération de cette fiche n’autorise pas la variante demandée ; ne pas réécrire sa structure.','source_and_role_domain_fixed_no_individual_basis_for_higher_intensity':'Domaine du rôle et de la fiche fixé ; besoin individuel d’une intensité supérieure non établi.'}
text='# Audit de référence V11\n\nMême cohorte : deux profils synthétiques Ironman, ambition finisher, niveau trained, budget déclaré de 600 min et mêmes disponibilités. Les deux calendriers V11 sont reproduits exactement sous l’horloge de scénario figée avant comparaison. Aucune donnée historique réelle n’est lue ou complétée.\n'
for r in rows:
 a=r['baselineAudit'];text+='\n## '+r['profile']+'\n\n'+table(['Semaine','Type','Natation','Vélo','Course','Soutien','Total','Séances déjà vues','Jours sans séance'],[[w['week'],w['type'],w['bySport']['swim'],w['bySport']['bike'],w['bySport']['run'],w['bySport']['strength'],w['total'],len(w['repeated']),w['fullRestDays']]for w in a['weeks']])
 text+='\n\nLes minutes sont prescrites, sans mesure de charge interne. En S2 et S3, les sept fiches sont toutes déjà vues. La répétition peut favoriser une comparaison de réponse et une exécution stable ; elle ne prouve ni stagnation ni progression physiologique. Les avertissements originaux de répétition restent présents.\n\n'
 text+='Le bloc comporte deux natations, deux vélos et deux courses en développement, puis deux/une/une en récupération. La mobilité conserve son propre rôle. La source de position répète quatre blocs de quinze minutes avec récupération cinq minutes ; seule la longue course du profil aérobie augmente en S3 pour un plancher de programmation.\n\n'
 text+=f'Récupération : {a["recovery"]["prescribed"]} min après {a["recovery"]["reference"]} min, soit {100*a["recovery"]["observedPrescriptionRatio"]:.1f}% comme constat, pas cible.\n'
text+='\n## Stimuli absents ou non démontrés\n\nNatation technique ciblée non démontrée ; force réelle absente malgré le nom du slot ; nutrition individuelle non exécutable ; bricks absents de ce bloc de base ; longues et continuité des phases spécifiques ultérieures non démontrées. Voir [spécificité Ironman](IRONMAN_SPECIFICITY.md). Aucun déficit n’est résolu en fabriquant une séance ou une capacité.\n\nLes familles 5 km,10 km,semi,marathon,trail,70.3 et autres objectifs ne reçoivent pas de nouveau bloc V12. Leur couverture logicielle existante est rejouée en non-régression ; elle ne valide pas sportivement ces deux prescriptions.'
write('BASELINE_AUDIT.md',text)
text='# Comparaison des modèles de progression\n\nCinq hypothèses préinscrites, examinées sur deux profils ; pas de permutations massives ni de recherche d’un meilleur taux de plans acceptés. Les plafonds, sources, phase, niveau et disponibilités V11 sont préservés.\n\n'
text+=table(['Profil','Modèle','Résultat expérimental','Justification ou limite'],[[r['profile'],models[p['model']],p['status'],reasons.get(p['reason'],'Bloc complet contrôlé ; toute réponse future et validation experte restent absentes.')]for r in rows for p in r['progression']])
text+='\n\nLes six refus de modèles ne sont pas six profils irréalisables. Le rôle prioritaire vélo du profil aérobie est déjà à180 min, la longue course de l’équilibré à90 min dans leurs enveloppes actuelles. Cela ne démontre pas une impossibilité physiologique générale ni un plafond futur immuable. Une autre preuve individuelle et une autre préparation pourraient modifier la décision.\n\nLe modèle de densité refusé demandait de raccourcir les repos dans la même fiche sans variante source admissible. Il ne condamne pas toute progression de densité : le modèle technique retenu la fait varier par deux recettes existantes. L’intensité supérieure n’est pas déclarée universellement dangereuse ; elle n’est pas justifiée pour ces rôles et ces données de base. Aucun HIT n’est ajouté pour satisfaire un quota historique.\n\n'
text+=table(['Recette source','Travail nominal en position','Bloc ininterrompu','Repos par intervalle','Total littéral borné','Fraction nominale travail/total'],[['C_BIKE_AERO_POSITION_DRILLS','60 min','10 min','5 min','85–90 min','66,7–70,6%'],['C_IM_AERO_HOLD','60 min','15 min','5 min','75–80 min','75–80%']])
text+='\n\nLa dernière récupération demeure une ambiguïté bornée ; les fractions ne sont pas une mesure du métabolisme. L’augmentation du temps ininterrompu et de la densité peut augmenter la contrainte posturale même sans ajouter de travail nominal. Ni efficacité ni équivalence de fatigue ne sont démontrées.\n\n## Arbitrage explicite en S1\n\nProfil aérobie : position80→85 min et course secondaire70→65 min, au-dessus de son plancher60. Profil équilibré : position75→85 min et plage nominale de nage55→45 min ; la course prioritaire reste inchangée. Aucun rôle essentiel n’est supprimé.\n\nLa nage conserve ses distances/répétitions et repos sources. Dix minutes de calendrier libérées ne prouvent donc pas dix minutes de travail physiologique retiré. Si le protocole complet ne tient pas dans45 min sans accélérer hors domaine, tronquer les répétitions ou changer les repos, la compensation doit être refusée et le calendrier revu. Cette faisabilité individuelle reste inconnue.\n\nS2 revient aux doses V11 et à la fiche de blocs15 min sous condition de réponse et revue, sans augmentation du volume hebdomadaire. Ce retour à une dose planifiée n’est pas une capacité nouvellement acquise. S3 maintient les stimuli ; le plancher natif de course du profil aérobie demeure une contrainte de programmation, pas une preuve d’adaptation.\n\nUn maintien sans changement reste une alternative retenue et pleinement argumentée. Les versions techniques sont des dossiers conditionnels, jamais des prescriptions libérées automatiquement. Les trois modèles de récupération sont examinés séparément [ici](RECOVERY_COMPARISON.md).'
write('PROGRESSION_MODELS.md',text)
for r in rows:
 selected=r['selected'];v=selected['attempt'];base=next(x['attempt']for x in r['progression']if x['model']=='justified_maintenance')
 name='MESOCYCLE_AEROBIC_PROFILE.md'if 'aerobic'in r['profile']else'MESOCYCLE_BALANCED_PROFILE.md'
 text='# Calendrier comparé — '+r['profile']+'\n\nVersion V12 candidate, non revue par un expert. Quatre semaines complètes,26 séances. Objectif Ironman/finisher, niveau trained, disponibilités identiques à V11. Les plafonds et l’historique de huit semaines sont explicitement fictifs. Aucune adaptation réelle n’est constatée.\n\n'
 d=r['input']['diagnostic'];text+=f'Priorité de discipline : {r["input"]["focus"]}. Limiteur présumé : VLamax, confiance diagnostique du modèle {100*d["confidenceGlobal"]:.0f}%. Incertitudes : '+ '; '.join(d['uncertainty']).rstrip('.')+'. Pas de fonction VLamax→minutes.\n\n'
 text+=table(['Semaine','Type','Total V11/V12','Natation V11/V12','Vélo V11/V12','Course V11/V12','Soutien V11/V12'],[[a['week'],a['type'],f'{b["total"]}/{a["total"]}',*[f'{b["totals"][s]}/{a["totals"][s]}'for s in ['swim','bike','run','strength']]]for a,b in zip(v['global']['rows'],base['global']['rows'])])
 text+='\n\nMinutes prescrites. Les totaux hebdomadaires sont inchangés ; cela ne prouve pas l’équivalence des charges internes ou de la récupération.\n'
 for w,b,records in zip(v['weeks'],base['weeks'],selected['records']):
  n=w['context']['week'];text+=f'\n## Semaine {n} — {w["context"]["weekType"]}, phase base\n\n'
  text+=table(['Jour','V11','V12'],[[day,source_sessions(b['validation']['week'],day),source_sessions(w['validation']['week'],day)]for day in ['lundi','mardi','mercredi','jeudi','vendredi','samedi','dimanche']])
  if n==1:text+='\n\nIntroduction candidate par blocs de10 min plutôt que15, avec60 min de travail nominal en position. Les minutes de repos source supplémentaires sont financées explicitement par une extension non prioritaire au-dessus de son minimum. Capacité posturale et faisabilité de la séance donatrice restent à confirmer.\n'
  elif n==2:text+='\n\nConsolidation candidate vers les blocs15 min, récupération par intervalle inchangée, retour aux doses V11. Transition retenue seulement pour revue après réponse utilisable, comparable, récupérée, explicitement sans douleur et position stable. Sinon la prescription est retenue, sans inférer une nouvelle capacité.\n'
  elif n==3:text+='\n\nMaintien des stimuli pour comparabilité. La longue course du profil aérobie rejoint75 min par plancher natif, dans son enveloppe75 ; le profil équilibré maintient90 min. Ce ne sont pas des règles de hausse universelle. Une réponse adverse retient la semaine, même si le plancher est techniquement requis.\n'
  else:text+='\n\nRécupération par les cinq rôles et minima sources, deux jours sans séance. Les trois disciplines restent présentes ; pas de remplissage automatique du budget inutilisé. Les alternatives250/265/270 min et leurs limites sont publiées séparément.\n'
  text+='\n'+table(['Rôle/source','Domaine','Min/retenu/max, min','But et suivi'],[[o['role']['sport']+'/'+o['role']['kind']+' · '+o['card']['id'],o['role']['domain'],f'{o["min"]}/{o["minutes"]}/{o["max"]}','Posture, exécution et récupération'if o['role']['kind']=='technical'else'Mobilité, sans dose de force réelle'if o['role']['kind']=='skill'else'Endurance et qualité d’exécution dans la discipline ; récupération à observer']for o in w['offers']])
  text+='\n\nContrôles hebdomadaires bloquants exécutés : aucun échec. Inconnues conservées : '+', '.join(w['validation']['unknowns'])+'. Les données de réponse et la revue experte ne sont pas acquises.\n'
 text+='\n## Évolution et réévaluation\n\nChaque séance dispose de son enregistrement prospectif dans comparison.json.gz : adaptation prioritaire, stimulus, dose admissible, réaction attendue, indicateur, récupération et arrêt/réévaluation. Les principes documentés de Lorang et les conventions TFCLab sont séparés. Voir [logique de décision](LORANG_DECISION_LOGIC.md).\n\nLes sources de position et longues autonomes sont distinctes. Les jours de proximité entre disciplines différentes restent visibles dans le calendrier : passer les contraintes de placement ne démontre pas l’absence d’interférence ou une récupération individuelle suffisante.\n\n'
 text+=table(['Code historique','Sévérité originale','Nombre'],[[k[0],k[1],n]for k,n in collections.Counter((i['code'],i['severity'])for i in v['legacy']).items()])
 text+='\n\nLes diagnostics historiques restent bruts. Les erreurs de portée sont accompagnées de témoins, les ratios restent une incompatibilité méthodologique réelle et les avertissements de placement/répétition restent visibles. Aucun résultat n’est déclaré conforme à tout le validateur historique ou validé scientifiquement.\n\nRevue nécessaire : hypothèse posturale, exécution du protocole complet dans le créneau donateur, symptômes et récupération, puis continuité et spécificité au-delà de ces quatre semaines. Aucun brick, protocole nutritionnel individuel ni dose de force ne sont artificiellement ajoutés.'
 write(name,text)
text='# Validation sportive : portées, contraintes et inconnues\n\nLes validateurs historiques et V11 ne sont ni modifiés ni désactivés. validateWeek reçoit le vrai contexte de chaque semaine ; les contrôles de bloc portent sur les quatre semaines. Les sorties historiques de préparation16 semaines sont archivées brutes, parallèlement. Le classement ci-dessous ne change aucune sévérité ni aucun statut de conformité historique.\n'
for r in rows:
 a=r['selected']['attempt'];text+='\n## '+r['profile']+'\n\n'+table(['Code historique','Sévérité','Interprétation avec témoin','Nombre'],[[k[0],k[1],k[2],n]for k,n in collections.Counter((i['original']['code'],i['original']['severity'],i['classification'])for i in a['issueWitnesses']).items()])
 aggregates=a['global']['ratios']['aggregates'];total=next(x for x in aggregates if x['period']=='all_training')
 text+='\n\n'+table(['Discipline','Séances physiques','Minutes prescrites','Part en nombre','Part en minutes'],[[s,total['legacySessionCount'][s],total['knownMinutes'][s],f'{total["legacySessionPct"][s]:.1f}%',f'{total["durationPctBounds"][s]["min"]:.1f}%']for s in ['swim','bike','run']])
 text+='\n\nAucun brick : il n’existe ici aucune composante supposée. Soutien/mobilité exclu du dénominateur d’endurance. Ces minutes sont des prescriptions ; le temps réellement passé dans chaque domaine reste inconnu.\n'
text+='\n## Témoins et limites\n\n- Les contrôles de couverture attendent16 semaines et en observent4. Dans les audits originaux de continuité/fréquence, les déficits des semaines couvertes sont vides ; le code échoue aussi sur le calendrier complet manquant. Ce témoin établit la portée, sans annuler l’erreur brute.\n- Le titre de bloc ne satisfait pas le H1 d’un plan complet ; c’est un écart de format conservé. La sérialisation technique du bloc, les sept jours et les sources sont contrôlés indépendamment.\n- Les erreurs sport_ratio restent des divergences méthodologiques ; elles ne sont pas assimilées à de simples erreurs de portée. Les fréquences et minutes diffèrent, sans que cela démontre l’optimalité des nouvelles parts. Les quatre semaines ne couvrent pas tout le premier bloc natif de génération.\n- Les avertissements de layout et de répétition sont réels. Leur diminution éventuelle ne suffit pas à choisir un modèle. Aucun avertissement significatif nouveau n’est accepté par simple reclassement.\n- Les plages source, planchers, plafonds individuels, disponibilités, jours de repos, espacement candidat, domaines et contrôles de charge existants restent actifs. Les bornes de programmation ne deviennent pas des certificats de sécurité.\n- Fatigue réelle, charge interne, chronologie de certaines fiches et faisabilité individuelle du protocole complet dans les créneaux restent inconnues. La force et nutrition réelles manquent ; voir la revue de spécificité.\n\nLes deux versions n’ajoutent aucune erreur critique ni avertissement historique par rapport à V11. Elles conservent chacune7 erreurs et30 avertissements bruts (V11 :7 et31). La réduction d’un avertissement de répétition correspond à une source effectivement différente en S1, pas à une réécriture de l’indicateur. Cette variation n’est pas une preuve d’efficacité.\n\nTypage et tests logiciels passent ; conformité sportive aux contrôles candidats exécutés, pertinence générale et validation experte sont des niveaux différents. Aucune adaptation physiologique obtenue, sécurité individuelle générale, préparation Ironman complète ou validation experte n’est attestée.'
write('SPORTING_VALIDATION.md',text)
# Metrics derive unique calendars rather than inflating the cohort by hypothesis count.
unique={hashlib.sha256(json.dumps(x['attempt']['plan'],sort_keys=True).encode()).hexdigest()for r in rows for x in r['progression']+r['recovery']if x.get('attempt')}
dashboard={'version':'det-v12-1','recommendation':'NO-GO','distinctProfiles':len(rows),'progressionHypothesesPerProfile':5,'recoveryHypothesesPerProfile':3,'distinctComputedCalendars':len(unique),'selectedConditionalVersions':len(rows),'selectedWeeksPerVersion':4,'decisionRecordsPerVersion':[sum(len(w['decisions'])for w in r['selected']['records'])for r in rows],'actualObservationsAdded':0,'expertReviewed':0,'profiles':[{'id':r['profile'],'model':r['selected']['model'],'weeklyMinutes':[w['total']for w in r['selected']['attempt']['global']['rows']],'weeklyMetrics':r['selected']['attempt']['global']['rows'],'divergences':r['selected']['divergences'],'rawErrors':next(x['rawLegacyErrors']for x in summary if x['profile']==r['profile']),'rawWarnings':next(x['rawLegacyWarnings']for x in summary if x['profile']==r['profile'])}for r in rows]}
(R/'dashboard.json').write_text(json.dumps(dashboard,indent=2))
counts={}
for name,expected in [('experimental',112),('historical',2999)]:
 log=(R/'evidence/validation'/f'{name}.txt').read_text();assert re.search(r'Tests\s+'+str(expected)+r' passed',log),name
 counts[name]={'passed':expected,'skipped':45 if name=='experimental'else 1,'todo':0 if name=='experimental'else 6,'log':f'evidence/validation/{name}.txt'}
assert re.search(r'Tests\s+12 passed',(E/'tests.txt').read_text())
validation={'version':'det-v12-1','types':'passed','nodePassed':62,**counts,'targetedPassed':12,'targetedOverlapsExperimental':True,'targetedOptInEvidenceTests':2,'reproducibility':repro,'fullPreparationSportingAttestation':False,'expertReviewed':False}
(R/'validation-summary.json').write_text(json.dumps(validation,indent=2))
text='# Résultats V12 — DRAFT / NO-GO\n\nDeux versions de quatre semaines sont préparées et comparées à V11, sur les mêmes profils synthétiques. Le progrès démontré porte sur la prescription prospective : évolution du stimulus explicitée, arbitrage de calendrier, suivi et conditions de réévaluation ; aucune adaptation physiologique obtenue n’est revendiquée.\n\n'
text+=table(['Profil','S1','S2','S3','S4','Changement candidat en S1'],[[r['profile'],*[w['total']for w in r['selected']['attempt']['global']['rows']],'Position6×10 au lieu de4×15 ; extension non prioritaire réduite explicitement']for r in rows])
text+='\n\nLes totaux hebdomadaires sont identiques à V11. La position passe ensuite aux blocs15 min sous condition de réponse et revue. Le travail nominal en position reste60 min, avec récupération de5 min par intervalle ; le temps ininterrompu et la densité nominale changent. Leur coût physiologique n’est pas démontré équivalent. Chaque version contient26 séances et26 décisions prospectives.\n\n'
text+=f'Cinq modèles de progression et trois de récupération sont comparés par profil. Ils représentent {len(unique)} calendriers calculés distincts sur deux profils, pas seize athlètes ni seize configurations indépendantes. Les variantes de récupération sont comparées sur la référence V11 complète ; elles ne sont pas combinées au modèle technique sélectionné ni adoptées dans V12. Les modèles de durée prioritaire, repos raccourci dans la même fiche et intensité supérieure ne sont pas retenus faute de marge ou de contrat/preuve approprié. Le maintien nul reste une alternative justifiée.\n\n'
text+='La récupération250 min reste la référence de minima pour comparaison, pas une dose optimale.270 min et, pour l’équilibré,265 min passent également les contrôles exécutés ; les retours manquent pour choisir biologiquement. Le témoin nage aérobie identique à250 n’est pas compté comme nouveau calendrier.\n\n## Validation\n\nTypage réussi ;62 tests de gouvernance,112 tests expérimentaux réussis (45 opt-in ignorés),2999 tests historiques réussis (1 ignoré,6 todo). Les12 tests ciblés de preuve recouvrent la suite expérimentale et deux tests opt-in ; ils ne sont pas additionnés comme couverture indépendante. Deux processus indépendants produisent exactement les mêmes quatre artefacts. Les références V2–V11 et les600 configurations historiques restent inchangées et ne sont pas régénérées.\n\nLes contrôles hebdomadaires et globaux exécutés passent, sans nouvelle erreur critique ni nouvel avertissement historique relatif à V11. Chaque version conserve7 erreurs et30 avertissements historiques bruts. Les témoins de portée, défauts techniques de format, incompatibilités méthodologiques de ratios, avertissements et inconnues sont distingués ; aucune sévérité n’est modifiée. Aucun passage des tests n’est assimilé à une revue experte.\n\n## Limites et arbitrages avant promotion\n\n1. Revue indépendante de l’hypothèse posturale et du calendrier :10→15 min par bloc,60 min de travail nominal, récupération et proximité des autres disciplines. Une fiche planifiée ne prouve pas une capacité déjà acquise.\n2. Faisabilité individuelle du protocole complet dans le temps donateur, particulièrement la nage55→45 min sans modifier distances, repos ou domaine. Si ce n’est pas réalisable, la compensation et le plan doivent être refusés ou revus.\n3. Réponses utilisables, comparables, récupération et symptômes avant chaque transition ; les six scénarios de retour par profil sont fictifs et ne libèrent jamais automatiquement une prescription.\n4. Force réelle, nutrition individuelle, longues et bricks ultérieurs restent non démontrés. Un témoin de brick existant annonce30–45 min pour au moins55 min de contenu ; aucune insertion ou correction de production n’est effectuée.\n\nLes principes documentés de Lorang sont séparés des conventions de catalogue et hypothèses TFCLab. Aucun pourcentage universel de progression/récupération, formule de dose optimale, nouvelle capacité acquise ou intensité hebdomadaire obligatoire n’est introduit. Aucun plan Ironman entier ni nouvelle disponibilité Coach Preview n’est déclaré. Les autres familles d’objectifs disposent d’une non-régression logicielle, pas de nouveaux blocs V12 sportivement attestés.\n\nLe code est exclusivement expérimental. Aucun moteur/validateur de production, donnée réelle, accès Nolio, migration, fusion, déploiement ou dépense. PR420 reste en brouillon et NO-GO. Voir [les dossiers](README.md) et [le registre de reprise](REPRISE.md).'
write('V12_RESULTS.md',text)
print(json.dumps({'profiles':len(rows),'distinctCalendars':len(unique),'decisions':dashboard['decisionRecordsPerVersion'],'replayIdentical':True}))
